// ===== 幽香书房 原生书源 函数库 v6（2026-10-16 抗 WAF 版）=====

// ── 0. 接口主机归一 ─────────────────────────────────────────────────────
// 目录接口是 POST，而裸域/http 会把它 301 成 GET（请求体丢失）→ 403。
fn yxApiRoot(host) {
  let h = replace(str(host), '^https?://', '', '')
  h = replace(h, '^www\\.', '', '')
  h = replace(h, '/[\\s\\S]*$', '', '')
  return 'https://www.' + h
}

// ── 1. 目录接口加密 ─────────────────────────────────────────────────────
// ⚠ 站点会**轮换 AES 密钥**（封装在 /templates/js/<32位hash>.js 里，文件名随 hash 变）。
//   旧密钥 = 服务端解密失败 = HTTP 403 {"code":-1,"msg":"Error"} —— 这不是风控！
//   所以 key/iv 改成从站点自己的脚本现取（cache.site/jsName/js），取不到才用下面的常量兜底。
fn yxAes(plain, key, iv) {
  let k = str(key)
  let v = str(iv)
  if (len(k) != 32) { k = 'SatdUcOtSLhcPw2v64B8oRToIZZt0Hdr' }
  if (len(v) != 16) { v = '8075311411457704' }
  return urlencode(bytesBase64(encrypt('AES/CBC/PKCS5Padding', plain, k, v)))
}

// 探针请求体（书码由首页现取；key/iv 由密钥脚本现取）
fn yxProbeBody(bid, key, iv) {
  let b = yxOrBid(bid)
  return 'data=' + yxAes('{\"id\":\"' + b + '\",\"page\":1}', key, iv)
}

// 首页里第一个书级链接（/book/XXXX.html）→ 探针书码，永不过期
fn yxFirstBid(html) {
  let m = match(str(html), '/book/([A-Za-z0-9]+)\\.html', 1)
  if (m == null) { return '' }
  return str(m)
}
fn yxOrBid(bid) {
  let s = trim(str(bid))
  if (len(s) < 2 || len(s) > 16) { return 'QBXF' }
  return s
}

// 接口地址：带上 &b=<书码>，让每本书的地址彼此不同
// （否则「探针」和「目录第 1 页」的 URL 完全一样，真机引擎会把后者当成重复地址过滤掉 → 少 100 章）
fn yxApiUrl(api, bid, page) {
  return str(api) + '/index.php?action=loadChapterPage&i=' + str(page) + '&b=' + str(bid)
}
// 前 100 章由详情页内嵌目录直接给出（真实名、零风险），所以接口只需要从第 2 页开始
fn yxFront(html, bid) {
  let t = yxTotal(html, bid)
  if (t > 100) { return 100 }
  return t
}

// 目录请求体
fn yxBody(bid, page, key, iv) {
  return 'data=' + yxAes('{\"id\":\"' + str(bid) + '\",\"page\":' + str(page) + '}', key, iv)
}

// ── 1b. 密钥自愈用的三个小工具 ──────────────────────────────────────────
// 'a|b' 取第 idx 段
fn yxSplit(s, idx) {
  let parts = split(str(s), '|')
  return str(default(parts[int(str(idx), 0)], ''))
}
// 详情页里引用的 32 位 hash 脚本名（站点的 AES 封装就在这个文件里）
fn yxJsName(html) {
  let m = match(str(html), '/templates/js/([A-Za-z0-9]{32})', 1)
  if (m == null) { return '' }
  return str(m)
}
// 从密钥脚本里取 "key|iv"
fn yxKeyIv(js) {
  let s = str(js)
  let k = match(s, 'AESCrypt\\(.([A-Za-z0-9]{32}).', 1)
  let v = match(s, 'parse\\(.([0-9]{16}).\\)', 1)
  if (k == null || v == null) { return '' }
  let ks = str(k)
  let vs = str(v)
  if (len(ks) != 32 || len(vs) != 16) { return '' }
  return ks + '|' + vs
}

// ── 2. 目录分页页数（<option value="N">1-100章</option> 的个数）────────────
fn yxPageCount(html) {
  let n = len(matchAll(str(html), '<option value="[0-9]+">', 0))
  if (n < 1) { n = 1 }
  return n
}

// ── 2b. <option> 里最大的结束章号（仅作最后兜底，是上界）────────────────
fn yxOptEnd(html) {
  let mx = 0
  for s in matchAll(str(html), '<option value="[0-9]+">([^<]*)</option>', 1) {
    let m = match(str(s), '-([0-9]+)\\s*章', 1)
    if (m != null) {
      let n = int(str(m), 0)
      if (n > mx) { mx = n }
    }
  }
  return mx
}

// ── 2c. 全页「同名书章节链接」的最大章号 ────────────────────────────────
// 这是本源的**关键修复**：详情页上同名书的章节链接有两处 ——
//   ① <ul id="ul_all_chapters"> 内嵌固定 100 章；
//   ② 头部「最新章节」块，20 条，末条就是全书最后一章。
// 取全页最大值 = 真实总章数（离线 8/8 精确命中：QBXF=116 01CL=338 QOPB=852
// IPKM=607 P3OT=652 DRKM=66 CFOT=29 3ORK=11；其中 QOPB 的 852 与接口全量
// 目录 904 条 / 章号上限 852 完全一致）。
// 注意：站点的「目录<span>（N章）」对一部分书写成 0 章（实测 QOPB/IPKM），
//       只认它就会退化成「只有 100 章」—— 这正是用户反馈的那个 bug。
fn yxPageMax(html, bid) {
  let b = str(bid)
  if (b == '') { return 0 }
  let mx = 0
  for s in matchAll(str(html), '/book/' + b + '-([0-9]+)\\.html', 1) {
    let n = int(str(s), 0)
    if (n > mx) { mx = n }
  }
  return mx
}

// ── 3. 总章数：多来源取最大（全部来自同一个详情页，零额外请求）──────────
fn yxTotal(html, bid) {
  let h = str(html)
  let t = 0
  // ① 目录<span>（N章）
  let sp = match(h, '目录<span>（\\s*([0-9]+)\\s*章', 1)
  if (sp != null) { t = int(str(sp), 0) }
  // ② og:novel:latest_chapter_url 的章号（部分书没有这个 meta）
  let og = match(h, 'og:novel:latest_chapter_url"[^>]*content="[^"]*?-([0-9]+)\\.html', 1)
  if (og != null) {
    let n = int(str(og), 0)
    if (n > t) { t = n }
  }
  // ③ 全页同名书链接最大章号（最可靠，span 为 0 的书也靠它）
  let pm = yxPageMax(h, bid)
  if (pm > t) { t = pm }
  // ④ 三个都没有 → 用 <option> 上界兜底（宁多勿少）
  if (t < 1) { t = yxOptEnd(h) }
  return t
}

// ── 3b. 接口要抓多少页：<option> 页数与「按总章数算出的页数」取大 ─────────
fn yxTocPages(html, bid) {
  let p = yxPageCount(html)
  let total = yxTotal(html, bid)
  let need = 0
  let c = 0
  while (c < total && need < 200) {
    need = need + 1
    c = c + 100
  }
  if (need > p) { p = need }
  if (p < 1) { p = 1 }
  if (p > 200) { p = 200 }
  return p
}

// ── 4. 取书码 ───────────────────────────────────────────────────────────
fn yxBid(url) {
  let b = match(str(url), '/book/([A-Za-z0-9]+)\\.html', 1)
  if (b == null) { return '' }
  return str(b)
}

// ── 5. og:description ───────────────────────────────────────────────────
fn yxOgDesc(html) {
  let h = str(html)
  let m = match(h, '<meta[^>]*property="og:description"[^>]*content="([\\s\\S]*?)"', 1)
  if (m == null) { m = match(h, '<meta[^>]*content="([\\s\\S]*?)"[^>]*property="og:description"', 1) }
  if (m == null) { return '' }
  return trim(replace(str(m), '\\s+', ' ', 'g'))
}

// ── 6. 降级路径：用详情页自己把整本目录铺出来（零额外请求）───────────────
// 名字来源（同一页）：<ul id="ul_all_chapters"> 的 1..100 章 + 头部「最新章节」
// 的最后 20 章（真实标题）。中间取不到的章号给「第N章」占位，URL 一律按
// /book/{书码}-{章号}.html 构造 —— 站点保证该形状可直接打开。
// ⚠ 必须限定同名书（/book/{bid}-N.html），否则「相关推荐」的其它书会混进来。
fn yxTocFill(html, bid, root, total) {
  let b = str(bid)
  if (b == '') { return [] }
  let base = str(root)
  if (!endsWith(base, '/')) { base = base + '/' }
  let lim = int(str(total), 0)
  if (lim < 1) { return [] }
  let titles = list(lim + 1, '')
  for c in split(str(html), '<a ') {
    let cs = str(c)
    let hf = match(cs, 'href="/book/' + b + '-([0-9]+)\\.html"', 1)
    if (hf != null) {
      let no = int(str(hf), 0)
      if (no > 0 && no <= lim) {
        let tag = match(cs, '^[^>]*>', 0)
        let ti = null
        if (tag != null) { ti = match(str(tag), 'title="([^"]*)"', 1) }
        if (ti == null) { ti = match(cs, '>([^<]*)</a>', 1) }
        let t = trim(str(ti))
        if (t != '') { titles[no] = t }
      }
    }
  }
  let out = []
  let k = 0
  let c = 1
  while (c <= lim) {
    let nm = titles[c]
    if (nm == null || nm == '') { nm = '第' + c + '章' }
    out[k] = { title: nm, url: base + 'book/' + b + '-' + c + '.html', order: c }
    k = k + 1
    c = c + 1
  }
  return out
}

// ── 7. 接口 JSON -> 统一列表 ────────────────────────────────────────────
fn yxTocApi(json) {
  if (json == null) { return [] }
  let d = get(json, 'data', null)
  if (d == null) { return [] }
  let out = []
  let k = 0
  for it in d {
    let u = str(default(get(it, 'chapterurl', ''), ''))
    if (u != '') {
      out[k] = { title: str(default(get(it, 'chaptername', ''), '')), url: u, order: int(default(str(get(it, 'chapterorder', '0')), '0'), 0) }
      k = k + 1
    }
  }
  return out
}

