// ── 11. 章节内分页 ──────────────────────────────────────────────────────
fn yxNext(html, base) {
  let u = match(str(html), '<a[^>]+id="next_url"[^>]+href="([^"]+)"', 1)
  if (u == null) { return '' }
  let s = str(u)
  if (!test(s, '-[0-9]+-[0-9]+\\.html')) { return '' }
  return absUrl(s, base)
}
